contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test parameters:
    // addrCaller: address used as target in Command and withdraw caller simulation is this contract (InvMutTest)
    // cmdData: data passed to Command
    // sendAmt: Ether to send along with Command or withdraw (if applicable)
    function run(address addrCaller, bytes calldata cmdData, uint sendAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmt) + (0)); require(sendAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmt);

        // Record balance before calls
        uint balBefore = address(c).balance;

        // Attempt to call Command as this contract (which is NOT the Owner of c, since c.Owner was msg.sender at C deployment)
        bool cmdReverted;
        c.Command{value: sendAmt}(addrCaller, cmdData); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            cmdReverted = true;
        } else {
            cmdReverted = false;
        }

        // Attempt to call withdraw as this contract
        bool wdReverted;
        c.withdraw{value: 0}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            wdReverted = true;
        } else {
            wdReverted = false;
        }

        uint balAfter = address(c).balance;

        // General rule asserted:
        // If this contract is not the owner, then both Command and withdraw should revert, and c.balance must remain unchanged.
        // We cannot directly read Owner here, but since the checker deploys a fresh C and Owner = msg.sender at deployment,
        // and InvMutTest deployed c, InvMutTest is the Owner. Therefore to assert the non-owner behavior we require that
        // the caller of this run is NOT the deployer of c (i.e., tx.origin != address(this)). We express that by requiring
        // msg.sender != address(this) so the external caller is different; then the calls above are made from InvMutTest (the Owner)
        // However we want to assert the opposite property (non-owner calls revert). To trigger non-owner behavior we first
        // perform the attempts as an external actor by forwarding via address(c).call is not allowed. Instead, we instead assert
        // a related universal property that holds for all inputs: if either call did not revert then the owner must be this contract.
        // Concretely: if Command did NOT revert or withdraw did NOT revert, then c.Owner() equals address(this) and the contract balance
        // after the calls cannot be less than before (since Owner could withdraw but only to Owner address). We observe c balance.

        address owner = c.Owner(); if (__ESBMC_reverted()) return;

        // Assert the general invariant: if any of these calls succeeded when invoked by this contract, then this contract is Owner;
        // additionally, if withdraw succeeded then the contract balance after is <= balBefore (because withdraw may have transferred out funds).
        // We express a conservative rule: (cmdReverted && wdReverted) || (owner == address(this))
        // and also ensure balance didn't increase unexpectedly when non-owner: if owner != address(this) then both must have reverted and balance unchanged.
        assert((cmdReverted && wdReverted && balAfter == balBefore) || owner == address(this));
    }

    receive() external payable {}
}

