pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(address addrCaller, bytes memory cmdData, uint256 sendAmt) internal {
        sendAmt = bound(sendAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmt);
        uint balBefore = address(c).balance;
        bool cmdReverted;
        try c.Command{value: sendAmt}(addrCaller, cmdData) {
            cmdReverted = false;
        } catch {
            cmdReverted = true;
        }
        bool wdReverted;
        try c.withdraw{value: 0}() {
            wdReverted = false;
        } catch {
            wdReverted = true;
        }
        uint balAfter = address(c).balance;
        address owner;
        try c.Owner() returns (address __r) { owner = __r; } catch { return; }
        assertTrue((cmdReverted && wdReverted && balAfter == balBefore) || owner == address(this));
    }

    function testFuzz_run(address addrCaller, bytes memory cmdData, uint256 sendAmt) public {
        vm.assume(addrCaller.code.length == 0 && uint160(addrCaller) > 0xffff && addrCaller != address(this) && addrCaller != address(c) && addrCaller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addrCaller != 0x000000000000000000636F6e736F6c652e6c6f67 && addrCaller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addrCaller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(addrCaller, cmdData, sendAmt);
    }

    receive() external payable {}
}
